  "implementation": "def solve(case):
    segments = case['segments']
    budget = case['budget']
    if not isinstance(segments, list) or len(segments) == 0:
        raise ValueError('segments must be a non-empty list')
    for seg in segments:
        if not all(k in seg for k in ('name','importance','minimum','capacity')):
            raise ValueError('segment missing required key')
        if not isinstance(seg['importance'], int) or not isinstance(seg['minimum'], int) or not isinstance(seg['capacity'], int):
            raise ValueError('importance, minimum, capacity must be integers')
        if seg['minimum'] < 0 or seg['capacity'] < seg['minimum']:
            raise ValueError('invalid segment bounds')
    if not isinstance(budget, int):
        raise ValueError('budget must be integer')
    total_min = sum(seg['minimum'] for seg in segments)
    total_cap = sum(seg['capacity'] for seg in segments)
    if budget < total_min or budget > total_cap:
        raise ValueError('budget out of feasible range')
    allocations = [seg['minimum'] for seg in segments]
    allocated = total_min
    while allocated < budget:
        best_ratio = -1.0
        best_idx = -1
        for idx, seg in enumerate(segments):
            cur = allocations[idx]
            if cur < seg['capacity']:
                ratio = seg['importance'] / (cur + 1)
                if ratio > best_ratio:
                    best_ratio = ratio
                    best_idx = idx
                elif ratio == best_ratio and idx < best_idx:
                    best_idx = idx
        if best_idx == -1:
            raise ValueError('unexpected allocation failure')
        allocations[best_idx] += 1
        allocated += 1
    by_name = {seg['name']: allocations[i] for i, seg in enumerate(segments)}
    return {'allocations': allocations, 'by_name': by_name, 'total': budget}"
}
